svg18=f'''<div class="math-diagram"><svg style="display:block;width:min(100%,240px);height:auto;margin:10px auto" viewBox="0 0 240 210" role="img" aria-label="포물선과 직선의 교점 A, B 및 y축 위 C, D"><path d="M 52.6,147.4 L100,140 L100,180 Z M100,140 L167.4,32.6 L100,100 Z" fill="#e6e6e6"/><path d="{curve18} M20,200 L180,40 M10,140 H230 M100,200 V10 M52.6,147.4 L100,180 M100,140 L167.4,32.6" fill="none" stroke="currentColor" stroke-width="1.2"/><g fill="currentColor" font-size="12"><text x="46" y="160">A</text><text x="170" y="32">B</text><text x="104" y="184">C</text><text x="104" y="98">D</text><text x="103" y="153">O</text><text x="228" y="152">x</text><text x="105" y="16">y</text></g></svg></div>'''
